import {t,translateUI,getLanguage,setLanguage,locale} from './i18n.js';
import {SCENARIOS,SECTIONS,CANVAS_BLOCKS,STRATEGY_FIELDS,newPlan,newScenario,scenarioData,migratePlan,validatePlan,forecast,metrics,progress,snapshot,restoreSnapshot,copyScenario,changedFields,demoPlans} from './model.js';
import {WorkspaceStore,ConflictError} from './storage.js';
const icons = {
 grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h5"/>',
 chart:'<path d="M3 3v18h18M7 15l5-6 4 3 5-8"/>',
 layers:'<path d="m12 3 10 5-10 5L2 8Z"/><path d="m2 12 10 5 10-5M2 16l10 5 10-5"/>',
 history:'<path d="M3 11a9 9 0 1 1 2.6 7.4M3 4v7h7M12 7v5l3 2"/>',
 settings:'<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/><path d="m10 3-1 3-3 1-3 3v4l3 1 1 3 3 3h4l1-3 3-1 3-3v-4l-3-1-1-3-3-3Z"/>',
 plus:'<path d="M12 5v14M5 12h14"/>', arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>', chevron:'<path d="m9 5 7 7-7 7"/>', down:'<path d="m6 9 6 6 6-6"/>', check:'<path d="m5 12 4 4L19 6"/>', search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>', close:'<path d="m6 6 12 12M6 18 18 6"/>', download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>', upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>', sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>', sprout:'<path d="M12 21V11M12 15C4 15 3 8 3 8s9-2 9 7ZM12 11c0-8 8-8 8-8s2 8-8 8Z"/>', trend:'<path d="m3 17 6-6 4 4 8-10M15 5h6v6"/>', wallet:'<path d="M20 8V5H5a2 2 0 0 1 0-4h13v4M3 3v16a2 2 0 0 0 2 2h15V8H5M16 12h5v5h-5Z"/>', people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6m2 5a6 6 0 0 1 3 6"/>', folder:'<path d="M3 6a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>', help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3v2M12 17h.01"/>', edit:'<path d="m16 3 5 5-12 12-6 1 1-6ZM14 5l5 5"/>', menu:'<path d="M4 6h16M4 12h16M4 18h16"/>', leaf:'<path d="M20 3C9 1 2 7 5 15s17 5 15-12ZM5 20 16 9"/>'
};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.file}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=document.querySelector('#app'),store=new WorkspaceStore();
let plans=[],activeId=localStorage.getItem('forma-active'),user=localStorage.getItem('forma-user')||'Mehdi',view='overview',scenario=localStorage.getItem('forma-scenario')||'realistic',section='summary',expanded=false,filter='all',search='',timer,toastTimer,queue=Promise.resolve(),generation=0;
const dirty=new Map(),failures=new Map();
const active=()=>plans.find(p=>p.id===activeId)||plans[0];
const current=()=>active()?.scenarios[scenario];
const editable=()=>active()?.owner===user;
const lang=(en,fr)=>getLanguage()==='fr'?fr:en;
const money=(n,compact=false,currency=active()?.currency||'MAD')=>new Intl.NumberFormat(locale(),{style:'currency',currency,currencyDisplay:'code',maximumFractionDigits:compact?1:0,...(compact?{notation:'compact'}:{})}).format(n);
const date=s=>new Date(s).toLocaleString(locale(),{dateStyle:'medium',timeStyle:'short'});
const nameOf=id=>t(SCENARIOS.find(s=>s.id===id)?.name||id);
const text=(en,fr)=>esc(lang(en,fr));
const badge=()=>store.mode==='folder'?lang('Connected folder','Dossier connecté'):store.mode==='server'?lang('Local files','Fichiers locaux'):lang('This browser only','Ce navigateur uniquement');
function toast(message){const el=document.querySelector('#toast');el.textContent=t(message);el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),5000);}
function saveLabel(){return failures.size?lang('Save conflict · export your draft','Conflit de sauvegarde · exportez le brouillon'):dirty.size?lang('Unsaved changes','Modifications à enregistrer'):lang('All changes saved','Toutes les modifications sont enregistrées');}
function updateSave(){const el=document.querySelector('#save-state');if(el)el.textContent=saveLabel();}
function touch(p=active()){p.updatedAt=new Date().toISOString();p.lastEditedBy=user;dirty.set(p.id,++generation);store.backup(plans);updateSave();clearTimeout(timer);timer=setTimeout(flush,450);}
function flush(){clearTimeout(timer);queue=queue.catch(()=>false).then(async()=>{let ok=true;for(const [id,stamp] of [...dirty]){const p=plans.find(x=>x.id===id);if(!p)continue;try{await store.save(structuredClone(p));if(dirty.get(id)===stamp)dirty.delete(id);failures.delete(id);}catch(e){ok=false;if(!failures.has(id))toast(e.message);failures.set(id,e.message);}}store.backup(plans);updateSave();return ok;});return queue;}
function nav(id,label,i){return `<button class="nav-item ${view===id?'active':''}" data-view="${id}">${icon(i)}<span>${esc(t(label))}</span></button>`;}
function button(action,label,i='arrow',primary=false,extra=''){return `<button class="button ${primary?'primary':''}" data-action="${action}" ${extra}>${icon(i)} ${esc(label)}</button>`;}
function heading(kicker,title,sub,actions='',userTitle=false){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1 ${userTitle?'data-user-content':''}>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`;}
function planSelect(){return `<select id="plan-select" class="plan-select" aria-label="Active business plan">${plans.map(p=>`<option value="${p.id}" ${p.id===active()?.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select>`;}
function projectHeading(sub){const p=active();return heading(text('BUSINESS PROJECT','PROJET D’ENTREPRISE'),esc(p.title),sub,planSelect()+button('export',t('Export plan'),'download')+(editable()?button('save-version',lang('Save project version','Enregistrer une version du projet'),'plus',true):''),true);}
function scenarioBar(){const p=active();return `${p.migratedFrom===1?`<div class="migration-note">${text('Your previous plan was copied into each scenario as a starting point. The three copies are now independent. Your saved history is preserved.','Votre ancien plan a été repris comme point de départ dans chaque scénario. Les trois copies sont désormais indépendantes. Votre historique est conservé.')}</div>`:''}<section class="scenario-workspace"><div class="scenario-tabs" aria-label="${text('Active scenario','Scénario actif')}">${SCENARIOS.map(s=>`<button data-scenario="${s.id}" class="${scenario===s.id?'selected':''}" aria-pressed="${scenario===s.id}"><b style="background:${s.color}"></b>${esc(t(s.name))}<small>${progress(p,s.id)} %</small></button>`).join('')}</div><p>${text('Each scenario has its own strategy, canvas, written plan, and financial assumptions.','Chaque scénario a sa stratégie, son canevas, son plan rédigé et ses hypothèses financières.')}</p></section>${editable()?'':`<div class="readonly-banner">${icon('people')}<span>${text('Reading a colleague’s project. Make your own copy to edit.','Vous consultez le projet d’un collègue. Créez votre copie pour le modifier.')} <b data-user-content>${esc(p.owner)}</b></span>${button('duplicate',lang('Create my copy','Créer ma copie'),'plus')}</div>`}`;}
function viewTabs(){return `<div class="plan-view-bar"><div class="segmented plan-view-tabs">${[['strategy','Scenario strategy','layers'],['canvas','Canvas view','grid'],['editor','Written plan','file'],['financials','Financial forecast','chart']].map(([v,label,i])=>`<button data-view="${v}" class="${view===v?'selected':''}">${icon(i)}${esc(t(label))}</button>`).join('')}</div><span class="plan-view-note">${esc(nameOf(scenario))} · ${badge()}</span></div>`;}
function render(){
 const p=active();document.body.classList.toggle('canvas-expanded',view==='canvas'&&expanded);document.documentElement.lang=getLanguage();document.title=lang('Forma — Three complete business scenarios','Forma — Trois scénarios d’entreprise');
 app.innerHTML=`<aside class="sidebar"><a class="brand" href="#" data-view="overview"><span class="brand-mark">${icon('layers')}</span>forma</a><div class="nav-label">${text('WORKSPACE','ESPACE DE TRAVAIL')}</div><nav>${nav('overview','Overview','grid')}${nav('plans','Business plans','file')}${nav('scenarios','Compare scenarios','layers')}${nav('canvas','Business canvas','grid')}${nav('financials','Financial forecast','chart')}${nav('versions','Version history','history')}${nav('collaboration','Work together','people')}</nav><div class="sidebar-lower">${nav('settings','Workspace settings','settings')}<button class="profile" data-view="settings"><span class="avatar">${esc(user.slice(0,1))}</span><span><b data-user-content>${esc(user)}</b><small>${badge()}</small></span></button></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu icon-button" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><span>Forma</span>${icon('chevron')}<strong>${esc(t({overview:'Overview',plans:'Business plans',scenarios:'Compare scenarios',strategy:'Scenario strategy',canvas:'Business canvas',editor:'Written plan',financials:'Financial forecast',versions:'Version history',collaboration:'Work together',settings:'Workspace settings'}[view]))}</strong></div><div class="topbar-right"><div class="language-switch" role="group" aria-label="Language"><button data-language="fr" aria-label="Français" aria-pressed="${getLanguage()==='fr'}">FR</button><button data-language="en" aria-label="English" aria-pressed="${getLanguage()==='en'}">EN</button></div><span class="save-indicator"><span></span><span id="save-state">${saveLabel()}</span></span></div></header><main class="${view==='canvas'?'canvas-page':''}">${p||['overview','plans','collaboration','settings'].includes(view)?({overview,plans:plansView,scenarios:compareView,strategy:strategyView,canvas:canvasView,editor:editorView,financials:financialView,versions:versionsView,collaboration:collaborationView,settings:settingsView}[view]||overview)():emptyState()}</main><footer><span>${badge()}</span><span>${text('One project · three independent scenarios · named project versions','Un projet · trois scénarios indépendants · des versions nommées')}</span></footer></div>`;
 translateUI(app);bind();if(p)localStorage.setItem('forma-active',p.id);localStorage.setItem('forma-scenario',scenario);
 app.querySelectorAll('[data-canvas-block]').forEach(grow);if(!editable())app.querySelectorAll('.edit-control').forEach(el=>el.disabled=true);
}
function emptyState(){return `<section class="empty-state">${icon('sprout')}<h2>${text('Start your business project','Commencez votre projet d’entreprise')}</h2><p>${text('Three independent scenarios are included from the start.','Les trois scénarios indépendants sont inclus dès le départ.')}</p>${button('new',t('Create a business plan'),'plus',true)}</section>`;}
function overview(){return heading(text('A CLEAR STRUCTURE FOR YOUR BUSINESS','UNE STRUCTURE CLAIRE POUR VOTRE ENTREPRISE'),text('One project. Three real scenarios.','Un projet. Trois vrais scénarios.'),text('Plan how your business will operate when conditions change.','Prévoyez comment votre entreprise fonctionnera selon les conditions.'),button('new',lang('New project','Nouveau projet'),'plus',true))+`<div class="project-intro panel"><div><span class="eyebrow">${text('HOW YOUR WORKSPACE WORKS','COMMENT FONCTIONNE VOTRE ESPACE')}</span><h2>${text('Build each scenario from the ground up.','Construisez chaque scénario dans son ensemble.')}</h2><p>${text('Write different offers, markets, pricing, operations, risks, milestones, and finances. Switch between scenarios without changing the others.','Définissez des offres, marchés, tarifs, opérations, risques, étapes et finances distincts. Modifiez un scénario sans changer les autres.')}</p>${button('examples',lang('Explore a fully written example','Explorer un exemple entièrement rédigé'),'layers')}</div><div class="intro-steps"><span>01 <b>${text('Create a project','Créez un projet')}</b></span><span>02 <b>${text('Develop three scenarios','Développez trois scénarios')}</b></span><span>03 <b>${text('Save and share versions','Enregistrez et partagez les versions')}</b></span></div></div><div class="section-heading"><h2>${text('Your projects','Vos projets')}</h2><button class="text-button" data-view="collaboration">${text('Connect your shared folder','Connecter votre dossier partagé')} ${icon('arrow')}</button></div><div class="project-list">${plans.map(projectCard).join('')||emptyState()}</div>${active()?`<section class="scenario-section"><div class="section-heading"><h2>${text('Explore the three scenarios','Explorez les trois scénarios')}</h2><span class="context-label" data-user-content>${esc(active().title)}</span></div><div class="scenario-cards detailed">${SCENARIOS.map(s=>scenarioCard(active(),s)).join('')}</div></section>`:''}`;}
function projectCard(p){return `<article class="project-row panel"><span class="plan-logo sage">${icon('leaf')}</span><div class="project-row-info"><button class="plan-title" data-action="open" data-id="${p.id}">${esc(p.title)}</button><p class="plan-description" data-user-content>${esc(p.description)}</p><span class="plan-owner"><b data-user-content>${esc(p.owner)}</b> · ${esc(date(p.updatedAt))}</span></div><div class="project-row-progress">${SCENARIOS.map(s=>`<span><b style="background:${s.color}"></b>${esc(t(s.name))}<strong>${progress(p,s.id)} %</strong></span>`).join('')}</div><div class="project-row-actions">${button('open',lang('Open project','Ouvrir le projet'),'arrow',false,`data-id="${p.id}"`)}${button('details',lang('Details','Détails'),'edit',false,`data-id="${p.id}"`)}</div></article>`;}
function plansView(){const shown=plans.filter(p=>(filter==='all'||p.owner===user)&&[p.title,p.description,p.owner].join(' ').toLowerCase().includes(search.toLowerCase()));return heading(text('YOUR BUSINESS PROJECTS','VOS PROJETS D’ENTREPRISE'),t('Business plans'),text('Each project contains all three scenarios and its full version history.','Chaque projet contient les trois scénarios et son historique complet.'),button('import',t('Import plan'),'upload')+button('new',lang('New project','Nouveau projet'),'plus',true))+`<div class="list-toolbar"><div class="segmented"><button data-filter="all" class="${filter==='all'?'selected':''}">${t('All plans')}</button><button data-filter="mine" class="${filter==='mine'?'selected':''}">${t('My plans')}</button></div><label class="search-box">${icon('search')}<input id="search" value="${esc(search)}" placeholder="${esc(t('Find a business plan…'))}" aria-label="Search plans"></label></div><div class="project-list">${shown.map(projectCard).join('')||`<p class="muted">${t('No plans match your search.')}</p>`}</div>`;}
function scenarioCard(p,s){const d=p.scenarios[s.id],m=metrics(p,s.id);return `<article class="scenario-card ${s.id}"><div class="scenario-card-top"><span class="scenario-icon">${icon(s.id==='pessimistic'?'sun':s.id==='optimistic'?'trend':'sprout')}</span><h3>${esc(t(s.name))}</h3><span>${progress(p,s.id)} %</span></div><p class="scenario-card-context" data-user-content>${esc(d.context||lang('No context written yet.','Contexte à rédiger.'))}</p><div class="scenario-meta"><span>${text('Written sections','Sections rédigées')} <b>${Object.values(d.sections).filter(v=>v.trim()).length}/7</b></span><span>${text('Canvas blocks','Cases du canevas')} <b>${Object.values(d.canvas).filter(v=>v.trim()).length}/9</b></span></div><div class="scenario-value"><strong>${money(m.revenue,true,p.currency)}</strong><span>${text('Annual revenue from this scenario’s own assumptions','CA annuel issu des hypothèses de ce scénario')}</span></div><button class="button" data-action="open-scenario" data-id="${s.id}">${text('Develop this scenario','Développer ce scénario')} ${icon('arrow')}</button></article>`;}
const strategyLabels={context:['Scenario context','Contexte du scénario'],strategy:['Decisions & actions','Décisions et actions'],risks:['Risks & contingency plan','Risques et plan de repli'],milestones:['Milestones & decision triggers','Étapes et critères de décision']};
const strategyHints={context:['What conditions define this scenario? Customers, competition, suppliers, and constraints.','Quelles conditions définissent ce scénario ? Clients, concurrence, fournisseurs et contraintes.'],strategy:['How will you change your offer, pricing, marketing, team, and operations?','Comment adaptez-vous votre offre, vos tarifs, votre marketing, votre équipe et vos opérations ?'],risks:['What could go wrong, and what would you do about it?','Qu’est-ce qui pourrait mal se passer et quelles seraient vos réponses ?'],milestones:['What must happen, by when, and what would make you change course?','Quelles étapes atteindre, à quelle échéance, et quels signaux vous feraient changer de direction ?']};
function strategyView(){return projectHeading(text('Develop a complete business scenario, then fill its canvas and financial plan.','Développez un scénario complet, puis son canevas et son plan financier.'))+scenarioBar()+viewTabs()+`<section class="strategy-sheet panel"><div class="section-heading"><h2>${esc(nameOf(scenario))} · ${text('Business strategy','Stratégie d’entreprise')}</h2>${editable()?button('copy-scenario',lang('Copy from another scenario','Copier depuis un autre scénario'),'layers'):''}</div><div class="strategy-field-grid">${STRATEGY_FIELDS.map(key=>`<label class="field"><span>${text(...strategyLabels[key])}</span><p class="field-hint">${text(...strategyHints[key])}</p><textarea class="edit-control" data-strategy="${key}" rows="7" placeholder="${text('Write your assumptions and decisions…','Rédigez vos hypothèses et vos décisions…')}">${esc(current()[key])}</textarea></label>`).join('')}</div></section>`;}
function grow(el){el.style.height='auto';el.style.height=Math.max(140,el.scrollHeight+2)+'px';}
function canvasView(){const d=current();return projectHeading(text('The canvas below belongs only to the selected scenario.','Le canevas ci-dessous appartient uniquement au scénario sélectionné.'))+scenarioBar()+viewTabs()+`<div class="canvas-toolbar"><span class="canvas-label">${esc(nameOf(scenario))} · ${t('Business Model Canvas')}</span><div>${button('print',t('Print / PDF'),'file')}${button('expand',expanded?t('Exit expanded view'):t('Expand canvas'),'grid')}</div></div><h2 class="print-scenario-name">${esc(nameOf(scenario))}</h2><div class="canvas-scroll" role="region" aria-label="Business Model Canvas. Scroll horizontally to see all nine blocks." tabindex="0"><div class="business-canvas">${CANVAS_BLOCKS.map(([key,label,prompt,hint,i])=>`<section class="canvas-cell ${key}"><div class="canvas-cell-heading"><h2>${esc(t(label))}</h2>${icon(i)}</div><p class="canvas-cell-prompt">${esc(t(prompt))}</p><label class="sr-only" for="canvas-${key}">${esc(t(label))}</label><textarea id="canvas-${key}" class="edit-control" data-canvas-block="${key}" placeholder="${esc(t(hint))}">${esc(d.canvas[key])}</textarea><div class="canvas-cell-print">${esc(d.canvas[key])}</div></section>`).join('')}</div></div><div class="canvas-footer">${t('Use short notes or bullet points. Every block autosaves. Scroll sideways on smaller screens.')}</div>`;}
function editorView(){const d=current(),def=SECTIONS.find(([key])=>key===section);return projectHeading(text('Write the detailed plan for the selected scenario.','Rédigez le plan détaillé du scénario sélectionné.'))+scenarioBar()+viewTabs()+`<div class="editor-grid"><aside class="section-list panel">${SECTIONS.map(([key,label],index)=>`<button class="section-link ${section===key?'selected':''}" data-section="${key}"><span class="section-number ${d.sections[key].trim()?'done':''}">${d.sections[key].trim()?icon('check'):index+1}</span>${t(label)}</button>`).join('')}</aside><section class="editor-paper panel"><div class="editor-eyebrow">${esc(nameOf(scenario))}<span>${t('Autosaved as you write')}</span></div><h2>${t(def[1])}</h2><p class="editor-subtitle">${t(def[2])}</p><div class="writing-prompt">${icon('sprout')}<p>${t(def[3])}</p></div><label class="sr-only" for="section-text">${t(def[1])}</label><textarea class="edit-control" id="section-text" placeholder="${esc(t('Your ideas belong here. Start writing…'))}">${esc(d.sections[section])}</textarea><div class="editor-bottom"><span id="word-count">${t(d.sections[section].trim().split(/\s+/).filter(Boolean).length+' words')}</span><button class="text-button" data-action="next">${t('Next section')}${icon('arrow')}</button></div></section></div>`;}
const assumptionLabels={monthlyRevenue:'Initial monthly revenue',fixedCosts:'Monthly fixed costs',variableCosts:'Variable costs (% of revenue)',startingCash:'Starting cash',monthlyGrowth:'Monthly revenue growth'};
function assumptionField(key,value){return `<label class="field"><span>${t(assumptionLabels[key])}</span><div class="input-affix"><input class="edit-control" type="number" data-assumption="${key}" value="${value}" min="${key==='monthlyGrowth'?-100:0}" max="${['variableCosts','monthlyGrowth'].includes(key)?100:1e12}" step="any" required><span>${['variableCosts','monthlyGrowth'].includes(key)?'%':active().currency}</span></div></label>`;}
function chart(p){const series=SCENARIOS.map(s=>({s,rows:forecast(p,s.id)})),max=Math.max(1,...series.flatMap(x=>x.rows.map(r=>r.revenue)));return `<svg class="forecast-chart" viewBox="0 0 800 270" role="img" aria-label="Monthly revenue projection for all three scenarios. The table below includes exact values.">${[0,1,2,3,4].map(i=>`<line x1="110" x2="755" y1="${30+i*47.5}" y2="${30+i*47.5}" stroke="#e4e9db" stroke-dasharray="4 4"/><text x="98" y="${34+i*47.5}" text-anchor="end">${esc(money(max*(1-i/4),true,p.currency))}</text>`).join('')}${series.map(({s,rows})=>`<path d="${rows.map((r,i)=>`${i?'L':'M'}${110+i*58.6} ${220-r.revenue/max*190}`).join(' ')}" fill="none" stroke="${s.color}" stroke-width="3"/>`).join('')}${Array.from({length:12},(_,i)=>`<text x="${110+i*58.6}" y="253" text-anchor="middle">M${i+1}</text>`).join('')}</svg>`;}
function financialView(){const p=active(),m=metrics(p,scenario),a=current().assumptions;return projectHeading(text('Enter actual amounts for this scenario. Nothing is derived from another scenario.','Saisissez les montants propres à ce scénario. Aucune valeur n’est dérivée d’un autre scénario.'))+scenarioBar()+viewTabs()+`<div class="financial-layout"><section class="panel assumptions"><div class="panel-heading"><h3>${esc(nameOf(scenario))}</h3></div><p class="muted">${text('Independent financial assumptions','Hypothèses financières indépendantes')}</p><form id="assumptions-form">${Object.keys(assumptionLabels).map(key=>assumptionField(key,a[key])).join('')}<button class="button primary full-width edit-control" type="submit">${t('Update forecast')}${icon('arrow')}</button></form><p class="field-hint">${text('Monthly revenue, costs, cash, and growth belong to this scenario only. Values start at zero on new projects.','Le CA, les charges, la trésorerie et la croissance appartiennent uniquement à ce scénario. Les montants d’un nouveau projet commencent à zéro.')}</p></section><div><div class="metric-grid"><div class="metric panel"><span>${t('Annual revenue')}</span><strong>${money(m.revenue,true)}</strong></div><div class="metric panel"><span>${t('Operating profit')}</span><strong class="${m.profit<0?'negative':'olive'}">${money(m.profit,true)}</strong><small>${t(m.margin.toFixed(1)+'% operating margin')}</small></div><div class="metric panel"><span>${t('Ending cash')}</span><strong>${money(m.endingCash,true)}</strong><small>${t(m.runway<0?'Cash stays positive':`Cash runs out in month ${m.runway+1}`)}</small></div></div><section class="panel chart-panel"><div class="panel-heading"><h3>${t('Revenue, in perspective')}</h3>${button('csv',t('Export CSV'),'download')}</div><div class="chart-legend">${SCENARIOS.map(s=>`<span><b style="background:${s.color}"></b>${t(s.name)}</span>`).join('')}</div>${chart(p)}</section></div></div><section class="panel table-panel"><div class="panel-heading"><h3>${esc(nameOf(scenario))} · ${t('Financial forecast')}</h3><span class="muted">${t('Operating break-even: '+(m.breakEven<0?'beyond month 12':'month '+(m.breakEven+1)))}</span></div><div class="table-scroll"><table><thead><tr>${['Month','Revenue','Total costs','Operating profit','Cash balance'].map(k=>`<th>${t(k)}</th>`).join('')}</tr></thead><tbody>${forecast(p,scenario).map(r=>`<tr><td>${t('Month '+(r.month+1))}</td><td>${money(r.revenue)}</td><td>${money(r.cost)}</td><td>${money(r.profit)}</td><td>${money(r.cash)}</td></tr>`).join('')}</tbody></table></div></section><p class="footnote">${t('Planning estimates before taxes, financing, depreciation, and capital expenditure. Adjust assumptions as you learn.')}</p>`;}
function compareView(){const p=active();return projectHeading(text('Compare the entire business model, decisions, and numbers for each scenario.','Comparez le modèle d’affaires, les décisions et les chiffres de chaque scénario.'))+`<div class="scenario-cards detailed">${SCENARIOS.map(s=>scenarioCard(p,s)).join('')}</div><section class="panel comparison-panel"><h2>${text('Your scenarios, side by side','Vos scénarios, côte à côte')}</h2><div class="table-scroll"><table class="scenario-comparison"><thead><tr><th>${text('Business dimension','Dimension du projet')}</th>${SCENARIOS.map(s=>`<th>${t(s.name)}</th>`).join('')}</tr></thead><tbody>${STRATEGY_FIELDS.map(key=>`<tr><th>${text(...strategyLabels[key])}</th>${SCENARIOS.map(s=>`<td data-user-content>${esc(p.scenarios[s.id][key]||lang('Not written yet.','Pas encore rédigé.'))}</td>`).join('')}</tr>`).join('')}${SECTIONS.map(([key,label])=>`<tr><th>${t(label)}</th>${SCENARIOS.map(s=>`<td data-user-content>${esc(p.scenarios[s.id].sections[key]||lang('Not written yet.','Pas encore rédigé.'))}</td>`).join('')}</tr>`).join('')}${Object.keys(assumptionLabels).map(key=>`<tr><th>${t(assumptionLabels[key])}</th>${SCENARIOS.map(s=>`<td>${['monthlyGrowth','variableCosts'].includes(key)?p.scenarios[s.id].assumptions[key]+' %':money(p.scenarios[s.id].assumptions[key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;}
function versionsView(){const p=active();return projectHeading(text('Each named version captures the whole project: all three scenarios, canvases, writing, and finances.','Chaque version nommée capture le projet entier : les trois scénarios, les canevas, les textes et les finances.'))+`<section class="version-explainer panel"><div><span>01</span><h3>${text('Working draft','Brouillon de travail')}</h3><p>${text('Autosave updates the current draft. It does not create a historical version.','L’enregistrement automatique actualise le brouillon. Il ne crée pas de version historique.')}</p></div><div><span>02</span><h3>${text('Named project version','Version nommée du projet')}</h3><p>${text('Save a version at a milestone. The three complete scenarios are preserved together.','Enregistrez une version à une étape importante. Les trois scénarios complets sont conservés ensemble.')}</p></div><div><span>03</span><h3>${text('Compare or restore','Comparer ou restaurer')}</h3><p>${text('See field-by-field changes. Restoring first saves a safety version of the current draft.','Consultez les changements champ par champ. Une restauration sauvegarde d’abord le brouillon actuel par sécurité.')}</p></div></section><section class="panel version-current"><span class="stat-icon sage">${icon('edit')}</span><div><h3>${text('Current draft · all three scenarios','Brouillon actuel · les trois scénarios')}</h3><p>${esc(date(p.updatedAt))} · <span data-user-content>${esc(p.lastEditedBy||p.owner)}</span></p></div>${button('open',lang('Continue editing','Poursuivre la rédaction'),'arrow',false,`data-id="${p.id}"`)}</section><div class="timeline">${p.versions.slice().reverse().map(v=>`<article class="panel version-item"><span class="timeline-dot">${icon('history')}</span><div class="version-info"><span class="version-number">V${v.number} · ${text('ALL THREE SCENARIOS','LES TROIS SCÉNARIOS')}</span><h3 data-user-content>${esc(v.name)}</h3><p>${esc(date(v.createdAt))} · <span data-user-content>${esc(v.author)}</span></p></div><div class="version-actions">${button('inspect-version',t('View snapshot'),'file',false,`data-id="${v.id}"`)}${button('compare-version',lang('Compare changes','Comparer les changements'),'layers',false,`data-id="${v.id}"`)}${editable()?button('restore',t('Restore'),'history',false,`data-id="${v.id}"`):''}</div></article>`).join('')||`<div class="empty-state"><h2>${text('No named versions yet','Aucune version nommée')}</h2><p>${text('Your draft is saved. Create a version when you want to preserve a milestone.','Votre brouillon est enregistré. Créez une version pour conserver une étape importante.')}</p>${editable()?button('save-version',t('Save your first version'),'plus',true):''}</div>`}</div>`;}
function collaborationView(){return heading(text('A SIMPLE WORKSPACE FOR TWO','UN ESPACE SIMPLE POUR DEUX'),text('Work together, with clear ownership.','Travaillez ensemble, avec des projets identifiés.'),text('Keep one project file per owner in your private Git repository.','Conservez un fichier par projet et par propriétaire dans votre dépôt Git privé.'),button('refresh',lang('Reload shared files','Actualiser les fichiers partagés'),'history'))+`<div class="storage-banner panel"><span class="stat-icon sage">${icon('folder')}</span><div><h2>${badge()}</h2><p>${store.mode==='browser'?text('Your drafts are private to this browser. Connect a folder to save real project files.','Vos brouillons sont propres à ce navigateur. Connectez un dossier pour enregistrer de vrais fichiers de projet.'):text('Projects and their versions are saved as readable JSON files.','Les projets et leurs versions sont enregistrés dans des fichiers JSON lisibles.')}${store.folder?` <b data-user-content>${esc(store.folder.name)}</b>`:''}</p></div>${button('connect',lang('Connect plans folder','Connecter le dossier des plans'),'folder',true)}</div><div class="collaboration-grid"><section class="panel settings-card"><h3>${text('Set up once, then work normally','Configurez une fois, puis travaillez normalement')}</h3><ol class="steps"><li>${text('Both people clone the same private Git repository.','Chaque personne clone le même dépôt Git privé.')}</li><li>${text('Choose your own name in Settings. Your colleague’s projects open in reading mode.','Choisissez votre propre nom dans les paramètres. Les projets du collègue s’ouvrent en lecture seule.')}</li><li>${text('Connect the data/plans folder of your clone, or run the local Node app.','Connectez le dossier data/plans de votre copie du dépôt, ou lancez l’application Node locale.')}</li><li>${text('Edit your project and save named versions when you reach a milestone.','Modifiez votre projet et enregistrez des versions nommées aux étapes importantes.')}</li><li>${text('Push your files. Your colleague pulls, then clicks Reload shared files.','Envoyez vos fichiers avec Git. Votre collègue les récupère, puis clique sur Actualiser les fichiers partagés.')}</li></ol><div class="storage-note">${icon('help')}<span>${text('Folder access works in Chrome and Edge on desktop. Other browsers can exchange JSON exports. Git push and pull remain manual; this website does not synchronize GitHub by itself.','L’accès aux dossiers fonctionne dans Chrome et Edge sur ordinateur. Les autres navigateurs peuvent échanger des exports JSON. Les opérations Git push et pull restent manuelles ; le site ne synchronise pas GitHub tout seul.')}</span></div></section><section class="panel settings-card"><h3>${text('Your daily Git workflow','Votre routine Git')}</h3><p>${text('Before editing, pull the latest files and reload them in Forma. The app checks whether a file changed before saving, to prevent silent overwrites.','Avant de modifier, récupérez les fichiers récents et actualisez-les dans Forma. L’application vérifie si un fichier a changé avant de l’enregistrer, pour éviter les écrasements silencieux.')}</p><pre class="git-example">git pull
# ${text('Edit your own project in Forma','Modifiez votre projet dans Forma')}
git add data/plans/
git commit -m "Update business project"
git push</pre><p>${text('The filename is stable, and every saved project version travels inside it.','Le nom du fichier reste stable, et toutes les versions enregistrées du projet l’accompagnent.')}</p>${button('export-all',lang('Back up all projects','Sauvegarder tous les projets'),'download')}${button('import',lang('Import a colleague’s project','Importer le projet du collègue'),'upload')}<p class="field-hint">${text('Names are local ownership labels, not authenticated accounts. Make your own copy when you want to adapt a colleague’s project.','Les noms identifient localement les propriétaires ; ce ne sont pas des comptes authentifiés. Créez votre copie pour adapter le projet d’un collègue.')}</p></section></div>${dirty.size||failures.size?`<div class="panel recovery-panel"><h3>${text('Your local draft needs attention','Votre brouillon local demande votre attention')}</h3><p>${text('Export a backup before reloading files from disk. Reloading replaces working drafts with the saved files.','Exportez une sauvegarde avant d’actualiser les fichiers. L’actualisation remplace les brouillons par les fichiers enregistrés.')}</p>${button('export-all',lang('Export my drafts','Exporter mes brouillons'),'download')}</div>`:''}`;}
function settingsView(){return heading(text('YOUR WORKSPACE','VOTRE ESPACE'),t('Workspace settings'),text('Set your identity and connect the place where your projects are saved.','Définissez votre identité et connectez le dossier de vos projets.'))+`<div class="settings-grid"><section class="panel settings-card"><h3>${t('Your identity')}</h3><form id="profile-form"><label class="field"><span>${t('Your display name')}</span><input name="name" value="${esc(user)}" maxlength="60" required></label><button class="button primary" type="submit">${t('Save profile')}</button></form><p>${text('Use a different name from your colleague. Project ownership helps avoid editing the wrong file. It is not an account password.','Utilisez un nom différent de celui de votre collègue. La propriété du projet évite de modifier le mauvais fichier ; ce n’est pas une protection par mot de passe.')}</p></section><section class="panel settings-card"><h3>${text('Storage and sharing','Stockage et partage')}</h3><p>${badge()}</p>${button('connect',lang('Connect plans folder','Connecter le dossier des plans'),'folder',true)}<button class="text-button" data-view="collaboration">${text('See the collaboration workflow','Voir le fonctionnement de la collaboration')}${icon('arrow')}</button><p>${text('MAD is the default currency. French and English are available in the header.','Le MAD est la devise par défaut. Le français et l’anglais sont disponibles en haut de page.')}</p>${button('examples',lang('Add a complete example','Ajouter un exemple complet'),'plus')}</section></div>`;}
function modal(title,body,wide=false){const root=document.querySelector('#modal-root');root.innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-heading"><h2>${title}</h2><button class="icon-button" data-close aria-label="Close dialog">${icon('close')}</button></div>${body}</section></div>`;translateUI(root);root.querySelector('[data-close]').onclick=closeModal;root.querySelector('.modal-overlay').onclick=e=>{if(e.target===e.currentTarget)closeModal();};root.querySelector('input,textarea,select,button:not([data-close])')?.focus();}
function closeModal(){document.querySelector('#modal-root').innerHTML='';}
function download(data,name,type='application/json'){const url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function createModal(){modal(lang('Create a business project','Créer un projet d’entreprise'),`<p class="muted">${text('The project will contain three independent, empty scenarios.','Le projet contiendra trois scénarios indépendants, prêts à être rédigés.')}</p><form id="new-form"><label class="field"><span>${t('Business name')}</span><input name="title" maxlength="160" required></label><label class="field"><span>${t('Description')}</span><textarea name="description" rows="3" maxlength="400"></textarea></label><div class="two-col"><label class="field"><span>${t('Industry')}</span><select name="industry">${['Other','Lifestyle & retail','Technology','Food & beverage','Consulting & services','Health & wellness','Education'].map(k=>`<option value="${esc(k)}">${t(k)}</option>`).join('')}</select></label><label class="field"><span>${t('Currency')}</span><select name="currency"><option value="MAD">MAD</option></select></label></div><div class="modal-footer"><button class="button primary" type="submit">${text('Create project','Créer le projet')}${icon('arrow')}</button></div></form>`);document.querySelector('#new-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),title=f.get('title').trim();if(!title)return;const p=newPlan({title,description:f.get('description').trim(),industry:f.get('industry'),owner:user});plans.unshift(p);activeId=p.id;scenario='realistic';view='strategy';touch(p);closeModal();await flush();render();};}
function saveVersionModal(){if(!editable())return;modal(lang('Save a project milestone','Enregistrer une étape du projet'),`<p class="muted">${text('This saves all three complete scenarios together. Autosave continues to update the working draft separately.','Cette action conserve les trois scénarios complets ensemble. L’enregistrement automatique continue d’actualiser le brouillon séparément.')}</p><form id="version-form"><label class="field"><span>${t('Version name')}</span><input name="name" maxlength="120" required placeholder="${text('For example: After supplier quotes','Exemple : Après les devis fournisseurs')}"></label><div class="modal-footer"><button class="button primary" type="submit">${text('Save project version','Enregistrer la version du projet')}</button></div></form>`);document.querySelector('#version-form').onsubmit=async e=>{e.preventDefault();if(!await flush()){toast(lang('Export your draft before resolving the save conflict.','Exportez votre brouillon avant de résoudre le conflit.'));return;}const name=new FormData(e.target).get('name').trim(),p=active();if(!name||p.versions.length>=1000)return;p.versions.push(snapshot(p,name,user));touch(p);closeModal();await flush();render();toast(t('Version saved. A moment worth keeping.'));};}
function inspectVersion(id,selected='realistic'){const v=active().versions.find(x=>x.id===id);if(!v)return;const p=migratePlan({...v.data,versions:[]}),s=p.scenarios[selected];modal(esc(v.name),`<div class="snapshot-meta">V${v.number} · ${esc(date(v.createdAt))} · ${esc(v.author)}</div><div class="segmented snapshot-tabs">${SCENARIOS.map(x=>`<button data-snapshot-case="${x.id}" class="${selected===x.id?'selected':''}">${t(x.name)}</button>`).join('')}</div>${STRATEGY_FIELDS.map(key=>`<h3>${text(...strategyLabels[key])}</h3><p class="snapshot-text">${esc(s[key]||t('Not written yet.'))}</p>`).join('')}${SECTIONS.map(([key,label])=>`<h3>${t(label)}</h3><p class="snapshot-text">${esc(s.sections[key]||t('Not written yet.'))}</p>`).join('')}<h3>${t('Business Model Canvas')}</h3><div class="snapshot-canvas">${CANVAS_BLOCKS.map(([key,label])=>`<div><h4>${t(label)}</h4><p data-user-content>${esc(s.canvas[key]||t('Not written yet.'))}</p></div>`).join('')}</div><h3>${t('Financial forecast')}</h3><div class="table-scroll"><table><tbody>${Object.keys(assumptionLabels).map(key=>`<tr><th>${t(assumptionLabels[key])}</th><td>${['variableCosts','monthlyGrowth'].includes(key)?s.assumptions[key]+' %':money(s.assumptions[key],false,p.currency)}</td></tr>`).join('')}</tbody></table></div>`,true);document.querySelectorAll('[data-snapshot-case]').forEach(b=>b.onclick=()=>inspectVersion(id,b.dataset.snapshotCase));}
function diffModal(fromId,toId='draft'){const p=active(),value=id=>id==='draft'?p:p.versions.find(v=>v.id===id)?.data,from=value(fromId),to=value(toId);if(!from||!to)return;const changes=changedFields(to,from);const options=selected=>`<option value="draft" ${selected==='draft'?'selected':''}>${text('Working draft','Brouillon actuel')}</option>`+p.versions.map(v=>`<option value="${v.id}" ${selected===v.id?'selected':''}>V${v.number} · ${esc(v.name)}</option>`).join('');const labelOf=c=>c.group==='sections'?t(SECTIONS.find(([k])=>k===c.key)?.[1]):c.group==='canvas'?t(CANVAS_BLOCKS.find(([k])=>k===c.key)?.[1]):c.group==='assumptions'?t(assumptionLabels[c.key]):c.group==='strategy'?lang(...strategyLabels[c.key]):c.key;modal(lang('Compare project versions','Comparer les versions du projet'),`<div class="two-col"><label class="field"><span>${text('Before','Avant')}</span><select id="diff-from">${options(fromId)}</select></label><label class="field"><span>${text('After','Après')}</span><select id="diff-to">${options(toId)}</select></label></div><p class="muted">${changes.length} ${text('changed fields across the project','champs modifiés dans le projet')}</p><div class="diff-list">${changes.map(c=>`<article class="diff-item"><h3>${c.scenario?esc(nameOf(c.scenario)):text('Project details','Détails du projet')} · ${esc(labelOf(c))}</h3><div class="two-col"><div class="diff-before" data-user-content>${esc(String(c.before)||'—')}</div><div class="diff-after" data-user-content>${esc(String(c.after)||'—')}</div></div></article>`).join('')||`<p>${text('No differences.','Aucune différence.')}</p>`}</div>`,true);document.querySelector('#diff-from').onchange=e=>diffModal(e.target.value,toId);document.querySelector('#diff-to').onchange=e=>diffModal(fromId,e.target.value);}
function restoreModal(id){if(!editable())return;const p=active(),v=p.versions.find(v=>v.id===id);if(!v)return;modal(lang('Restore all three scenarios','Restaurer les trois scénarios'),`<p>${text('Restore this named version as the working draft? All three scenarios will be restored. The current draft is first saved as a safety version.','Restaurer cette version comme brouillon actuel ? Les trois scénarios seront restaurés. Le brouillon actuel sera d’abord conservé dans une version de sécurité.')}</p><p data-user-content>${esc(v.name)}</p><div class="modal-footer">${button('confirm-restore',t('Restore version'),'history',true)}</div>`);document.querySelector('[data-action="confirm-restore"]').onclick=async()=>{if(!await flush())return;if(p.versions.length>=1000)return;const restored=restoreSnapshot(p,id,user);plans[plans.findIndex(x=>x.id===p.id)]=restored;touch(restored);closeModal();await flush();render();toast(t('Version restored. Your previous draft is safely saved.'));};}
function copyScenarioModal(){if(!editable())return;modal(lang('Use another scenario as a starting point','Utiliser un autre scénario comme point de départ'),`<p>${text('This replaces only the selected scenario. A safety version of the entire project will be saved first. The source scenario stays independent.','Cette action remplace uniquement le scénario sélectionné. Une version de sécurité du projet sera d’abord enregistrée. Le scénario source reste indépendant.')}</p><form id="copy-form"><label class="field"><span>${text('Copy into','Copier vers')} ${esc(nameOf(scenario))}</span><select name="source">${SCENARIOS.filter(s=>s.id!==scenario).map(s=>`<option value="${s.id}">${t(s.name)}</option>`).join('')}</select></label><div class="modal-footer"><button class="button primary" type="submit">${text('Copy scenario','Copier le scénario')}</button></div></form>`);document.querySelector('#copy-form').onsubmit=async e=>{e.preventDefault();if(!await flush())return;const p=active();if(p.versions.length>=1000)return;p.versions.push(snapshot(p,lang('Before scenario copy','Avant copie de scénario'),user));copyScenario(p,new FormData(e.target).get('source'),scenario);touch(p);closeModal();await flush();render();};}
function detailsModal(id){const p=plans.find(p=>p.id===id);if(!p)return;modal(t('Plan details'),`<form id="details-form"><label class="field"><span>${t('Business name')}</span><input name="title" value="${esc(p.title)}" maxlength="160" required ${p.owner!==user?'disabled':''}></label><label class="field"><span>${t('Description')}</span><textarea name="description" rows="3" maxlength="400" ${p.owner!==user?'disabled':''}>${esc(p.description)}</textarea></label><p class="muted">${text('Owner','Propriétaire')} : <span data-user-content>${esc(p.owner)}</span></p><div class="modal-footer">${button('export-details',t('Export plan'),'download')}${p.owner===user?`<button class="button primary" type="submit">${t('Save changes')}</button>`:''}</div></form>`);document.querySelector('[data-action="export-details"]').onclick=()=>download(p,p.id+'.json');document.querySelector('#details-form').onsubmit=async e=>{e.preventDefault();if(p.owner!==user)return;const f=new FormData(e.target);if(!f.get('title').trim())return;p.title=f.get('title').trim();p.description=f.get('description').trim();touch(p);closeModal();await flush();render();};}
async function importProjects(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{if(!input.files?.length)return;try{if(input.files[0].size>8e6)throw Error(t('Please select a file smaller than 8 MB.'));const json=JSON.parse(await input.files[0].text()),incoming=(Array.isArray(json)?json:[json]).map(p=>migratePlan(validatePlan(p)));if(!incoming.length)throw Error(t('The file contains no plans.'));if(new Set(incoming.map(p=>p.id)).size!==incoming.length)throw Error(t('The backup contains duplicate plan IDs.'));if(!await flush())return;const conflicts=incoming.filter(p=>plans.some(x=>x.id===p.id));const apply=async()=>{for(const p of incoming){await store.save(p);const i=plans.findIndex(x=>x.id===p.id);if(i<0)plans.push(p);else plans[i]=p;}store.backup(plans);activeId=incoming[0].id;view='scenarios';closeModal();render();toast(t(incoming.length+' plans imported.'));};if(conflicts.length){modal(lang('Review before replacing a project','Vérifiez avant de remplacer un projet'),`<p>${text('This import contains existing projects. Replacing them also replaces their working drafts and version histories. Download a backup first.','Cet import contient des projets existants. Leur remplacement inclut les brouillons et les historiques. Téléchargez d’abord une sauvegarde.')}</p><div class="modal-footer">${button('backup-import',lang('Download backup','Télécharger la sauvegarde'),'download')}${button('replace-import',t('Replace and import'),'upload',true)}</div>`);document.querySelector('[data-action="backup-import"]').onclick=()=>download(plans,'forma-before-import.json');document.querySelector('[data-action="replace-import"]').onclick=()=>apply().catch(e=>toast(e.message));}else await apply();}catch(e){toast(e instanceof SyntaxError?t('Could not import this file.'):e.message);}};input.click();}
async function connectFolder(){if(!await flush())return;const before=structuredClone(plans);localStorage.setItem('forma-before-folder',JSON.stringify(before));try{const loaded=await store.connect();for(const p of before.filter(p=>p.owner===user&&!loaded.some(x=>x.id===p.id))){await store.save(p);loaded.push(p);}plans=loaded;dirty.clear();failures.clear();activeId=plans.find(p=>p.owner===user)?.id||plans[0]?.id;view='collaboration';store.backup(plans);render();toast(lang('Folder connected. Your own new projects are saved there.','Dossier connecté. Vos nouveaux projets personnels y sont enregistrés.'));}catch(e){if(e.name!=='AbortError')toast(e.message);}}
async function reloadFiles(force=false){if(!force&&(dirty.size||failures.size)){modal(lang('Keep a backup before reloading','Conservez une sauvegarde avant d’actualiser'),`<p>${text('Reloading replaces unsaved drafts with the saved files. Export your drafts first.','L’actualisation remplace les brouillons non enregistrés par les fichiers sauvegardés. Exportez d’abord vos brouillons.')}</p><div class="modal-footer">${button('recovery-export',lang('Export my drafts','Exporter mes brouillons'),'download')}${button('recovery-reload',lang('Reload saved files','Charger les fichiers enregistrés'),'history')}</div>`);document.querySelector('[data-action="recovery-export"]').onclick=()=>download(plans,'forma-unsaved-drafts.json');document.querySelector('[data-action="recovery-reload"]').onclick=()=>reloadFiles(true);return;}try{plans=await store.load();dirty.clear();failures.clear();activeId=plans.find(p=>p.id===activeId)?.id||plans[0]?.id;closeModal();render();toast(lang('Projects reloaded from saved files.','Projets actualisés depuis les fichiers enregistrés.'));}catch(e){toast(e.message);}}
async function duplicateProject(){if(!active())return;const original=active(),p=structuredClone(original);p.id=crypto.randomUUID();p.title=(p.title+' · '+user).slice(0,160);p.owner=user;p.versions=[];p.copiedFrom={id:original.id,owner:original.owner};p.createdAt=new Date().toISOString();p.versions.push(snapshot(p,lang('My copy of the project','Ma copie du projet'),user));plans.unshift(p);activeId=p.id;touch(p);await flush();render();}
function bind(){
 app.querySelectorAll('[data-language]').forEach(b=>b.onclick=async()=>{await flush();setLanguage(b.dataset.language);render();});
 app.querySelectorAll('[data-view]').forEach(b=>b.onclick=async e=>{e.preventDefault();await flush();view=b.dataset.view;render();window.scrollTo(0,0);});
 app.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=async()=>{await flush();scenario=b.dataset.scenario;render();});
 app.querySelectorAll('[data-section]').forEach(b=>b.onclick=async()=>{await flush();section=b.dataset.section;render();});
 app.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});
 app.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{try{const a=b.dataset.action;
  if(a==='new')createModal();else if(a==='open'){await flush();activeId=b.dataset.id;scenario='realistic';view='strategy';render();window.scrollTo(0,0);}
  else if(a==='open-scenario'){await flush();scenario=b.dataset.id;view='strategy';render();window.scrollTo(0,0);}
  else if(a==='save-version')saveVersionModal();else if(a==='inspect-version')inspectVersion(b.dataset.id);else if(a==='compare-version')diffModal(b.dataset.id);else if(a==='restore')restoreModal(b.dataset.id);else if(a==='copy-scenario')copyScenarioModal();else if(a==='details')detailsModal(b.dataset.id);
  else if(a==='export'&&active())download(active(),active().id+'.json');else if(a==='export-all')download(plans,'forma-projects.json');else if(a==='import')await importProjects();else if(a==='connect')await connectFolder();else if(a==='refresh')await reloadFiles();else if(a==='duplicate')await duplicateProject();
  else if(a==='expand'){await flush();expanded=!expanded;render();}else if(a==='print'){await flush();window.print();}else if(a==='menu')document.querySelector('.sidebar').classList.toggle('mobile-open');
  else if(a==='next'){await flush();const i=SECTIONS.findIndex(([k])=>k===section);if(i===SECTIONS.length-1)view='financials';else section=SECTIONS[i+1][0];render();}
  else if(a==='csv'){const rows=forecast(active(),scenario),data='\uFEFF'+['Month','Revenue','Total costs','Operating profit','Cash balance'].map(t).join(',')+'\n'+rows.map(r=>[r.month+1,r.revenue.toFixed(2),r.cost.toFixed(2),r.profit.toFixed(2),r.cash.toFixed(2)].join(',')).join('\n');download(data,active().id+'-'+scenario+'.csv','text/csv');}
  else if(a==='examples'){for(const p of demoPlans(user)){activeId=p.id;if(plans.some(x=>x.id===p.id))continue;p.owner=user;plans.push(p);touch(p);}await flush();view='scenarios';render();}
 }catch(e){toast(e.message);}});
 const select=app.querySelector('#plan-select');if(select)select.onchange=async e=>{await flush();activeId=e.target.value;render();};
 const searchInput=app.querySelector('#search');if(searchInput)searchInput.oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;render();const el=app.querySelector('#search');el.focus();el.setSelectionRange(pos,pos);};
 app.querySelectorAll('[data-strategy]').forEach(el=>el.oninput=()=>{if(!editable())return;current()[el.dataset.strategy]=el.value;touch();});
 app.querySelectorAll('[data-canvas-block]').forEach(el=>el.oninput=()=>{if(!editable())return;current().canvas[el.dataset.canvasBlock]=el.value;el.closest('.canvas-cell').querySelector('.canvas-cell-print').textContent=el.value;grow(el);touch();});
 const writing=app.querySelector('#section-text');if(writing)writing.oninput=()=>{if(!editable())return;current().sections[section]=writing.value;app.querySelector('#word-count').textContent=t(writing.value.trim().split(/\s+/).filter(Boolean).length+' words');touch();};
 const af=app.querySelector('#assumptions-form');if(af){af.querySelectorAll('input').forEach(el=>el.oninput=()=>{if(!editable()||!el.validity.valid)return;current().assumptions[el.dataset.assumption]=Number(el.value);touch();});af.onsubmit=async e=>{e.preventDefault();if(!editable())return;await flush();render();toast(t('Forecast updated. A fresh perspective.'));};}
 const pf=app.querySelector('#profile-form');if(pf)pf.onsubmit=async e=>{e.preventDefault();const name=new FormData(pf).get('name').trim();if(!name||!await flush())return;user=name;localStorage.setItem('forma-user',user);render();toast(t('Profile updated. Welcome, '+user+'.'));};
}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.querySelector('.sidebar')?.classList.remove('mobile-open');}if(e.key==='Tab'){const m=document.querySelector('.modal');if(!m)return;const els=[...m.querySelectorAll('button,input,textarea,select')].filter(el=>!el.disabled),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('beforeunload',e=>{store.backup(plans);if(dirty.size){e.preventDefault();e.returnValue='';}});
window.addEventListener('storage',e=>{if(e.key==='forma-plans'&&store.mode==='browser')toast(lang('Another tab saved a project. Reload shared files before editing that project.','Un autre onglet a enregistré un projet. Actualisez les fichiers avant de modifier ce projet.'));});
async function init(){try{plans=await store.initial();}catch(e){toast(e.message);plans=[];}if(!SCENARIOS.some(s=>s.id===scenario))scenario='realistic';if(!plans.some(p=>p.id===activeId))activeId=plans.find(p=>p.owner===user)?.id||plans[0]?.id;render();}
init();
